CREATE TABLE IF NOT EXISTS t_p83915249_biotech_anime_store.planet_warehouses (id SERIAL PRIMARY KEY, planet_id INTEGER NOT NULL, player_id INTEGER NOT NULL, metal_stored INTEGER NOT NULL DEFAULT 0, energy_stored INTEGER NOT NULL DEFAULT 0, crystals_stored INTEGER NOT NULL DEFAULT 0, fuel_stored INTEGER NOT NULL DEFAULT 0, ore_stored INTEGER NOT NULL DEFAULT 0, alloy_stored INTEGER NOT NULL DEFAULT 0, components_stored INTEGER NOT NULL DEFAULT 0, max_capacity INTEGER NOT NULL DEFAULT 5000, warehouse_level INTEGER NOT NULL DEFAULT 1, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());